import{_ as s,l as i,o as e,c as l,v as t,p as n,x as r,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"CRDT","description":"","frontmatter":{"title":"CRDT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/crdt.md","filePath":"cs/crdt.md","lastUpdated":1789023840000}'),h={name:"cs/crdt.md"};function T(m,a,u,_,C,S){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="crdt" tabindex="-1">CRDT <a class="header-anchor" href="#crdt" aria-label="Permalink to &quot;CRDT&quot;">​</a></h1><div class="epigraph"><p>冲突无关：合并交换、结合、幂等，半格上的最小上界让并发写都不丢。代价是语义必须能写成这种代数。</p><footer>—— 据 Shapiro, Preguiça, Baquero and Zawirski, Conflict-free Replicated Data Types, SSS 2011 整理</footer></div><p>上一课<a href="/cs/lww-conflict">LWW</a>用假全序丢一边。缺口是<strong>不丢的合并</strong>：并发加一、并发往集合里加元素，结果应都在。本课钉 CRDT 的半格条件，不重写向量检出。后课会话保证是客户端视角，不是合并代数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>状态 CRDT：每个副本状态在半格里，收到他方状态就取 \\(\\sqcup\\)。\\(\\sqcup\\) 交换、结合、幂等 ⇒ 任意传播顺序收敛到同一上界。操作 CRDT：广播操作，补偿关系让乱序应用等价。缺口：不是任何业务都能找 \\(\\sqcup\\)。计数器可以；「唯一主键约束」很难；「转账不透支」通常要共识。</p><p>G-Counter、PN-Counter、G-Set、OR-Set、LWW-Register（寄存器仍是 LWW，只是嵌在半格里）是目录。RGA、WOOT 一类序列 CRDT 给协作编辑，本课点名不写变换细节。</p><p><span class="marginnote">SSS 2011 技术报告把 CvRDT 与 CmRDT 对齐。先前 Bayou 的提交是应用合并，不保证半格。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计：先写并发意图的交换图，再找单调状态。tombstone 让删除也单调（OR-Set）。压缩 tombstone 需要因果稳定——又用到<a href="/cs/vector-clocks">向量</a>或 GC 纪元。传播仍用反熵或广播，CRDT 不替代<a href="/cs/dynamo-anti-entropy">Dynamo</a>的运输层。</p>',9)),(e(),n(p,null,{default:r(()=>[d(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20OP%5B%22%E5%B9%B6%E5%8F%91%E6%9B%B4%E6%96%B0%22%5D%20--%3E%20ST%5B%22%E5%8D%95%E8%B0%83%E7%8A%B6%E6%80%81%22%5D%0A%20%20ST%20--%3E%20JOIN%5B%22%E2%8A%94%20%E5%90%88%E5%B9%B6%22%5D%0A%20%20JOIN%20--%3E%20CONV%5B%22%E4%B8%8E%E9%A1%BA%E5%BA%8F%E6%97%A0%E5%85%B3%E7%9A%84%E6%94%B6%E6%95%9B%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>不要把「JSON 随便 merge」叫 CRDT。也不要把多主数据库默认当半格。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>G-Counter：每副本只增自己的分量，合并取 max，求和。两个 +1 来自不同副本则和为 2，LWW 做不到。OR-Set：添加带唯一标签，删除记标签；合并并上标签集。唯一约束「键只出现一次」与并发添加冲突，半格给不出「选一个不丢另一个」的业务含义——那就要 LWW 或共识。</p><p>元数据膨胀是工程税：标签、向量、墓碑。不膨胀往往牺牲精确并发（又滑回 LWW）。正确性相对代数，不相对 NTP。</p><p>本课不把区块链账本当 CRDT：全局唯一花费是共识对象。也不写 Transformer 或权重量化。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证所有目录结构的完备性，不写 delta-CRDT 全文。后课默认：能半格化的对象用 CRDT 换无协调合并；不变式跨对象（不透支）仍要<a href="/cs/replicated-state-machine">复制状态机</a>或事务。会话保证下一课处理「我刚写的我看见」，那是客户端，不是 \\(\\sqcup\\)。</p><p>代数对了，乱序与重复投递就不再是冲突源。代数不对，协议再精也在藏 LWW。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CRDT：合并是半格上界，并发更新可都不丢。</li><li>不是所有不变量都能半格化。</li><li>运输层仍要反熵；墓碑要因果 GC。</li><li>出处：Shapiro et al., SSS 2011。</li></ul>',10))])}const E=s(h,[["render",T]]);export{D as __pageData,E as default};
